1	'use client'
2	
3	import { useState, useEffect, useCallback } from 'react'
4	import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
5	import { Typography } from '@/components/ui/typography'
6	import { Button } from '@/components/ui/button'
7	import { TeamMembersTable, type TeamMember } from '@/components/settings/team/TeamMembersTable'
8	import { TeamInvitesTable, type TeamInvite } from '@/components/settings/team/TeamInvitesTable'
9	import { InviteModal } from '@/components/settings/team/InviteModal'
10	import { DataState } from '@/components/shared/DataState'
11	import { EmptyState } from '@/components/shared/EmptyState'
12	import { PageError } from '@/components/shared/PageError'
13	import { ListSkeleton } from '@/components/skeletons'
14	import { Mail } from 'lucide-react'
15	
16	export default function TeamPage() {
17	  const [members, setMembers] = useState<TeamMember[]>([])
18	  const [invites, setInvites] = useState<TeamInvite[]>([])
19	  const [currentUserId, setCurrentUserId] = useState('')
20	  const [loading, setLoading] = useState(true)
21	  const [fetchError, setFetchError] = useState<Error | null>(null)
22	  const [showInviteModal, setShowInviteModal] = useState(false)
23	
24	  const fetchData = useCallback(async () => {
25	    setLoading(true)
26	    setFetchError(null)
27	    try {
28	      const [membersRes, invitesRes, meRes] = await Promise.all([
29	        fetch('/api/studio-members'),
30	        fetch('/api/team-invites'),
31	        fetch('/api/profile'),
32	      ])
33	
34	      if (!membersRes.ok) throw new Error('Failed to fetch members')
35	      const membersJson = await membersRes.json() as { data: TeamMember[] }
36	      setMembers(membersJson.data ?? [])
37	
38	      if (invitesRes.ok) {
39	        const invitesJson = await invitesRes.json() as { data: TeamInvite[] }
40	        setInvites(invitesJson.data ?? [])
41	      }
42	
43	      if (meRes.ok) {
44	        const meJson = await meRes.json() as { data: { id: string } }
45	        setCurrentUserId(meJson.data?.id ?? '')
46	      }
47	    } catch (err) {
48	      setFetchError(err instanceof Error ? err : new Error('Could not load team data'))
49	    } finally {
50	      setLoading(false)
51	    }
52	  }, [])
53	
54	  useEffect(() => { void fetchData() }, [fetchData])
55	
56	  const pendingCount = invites.filter((i) => i.status === 'pending').length
57	  const activeCount = members.filter((m) => !m.deactivated_at).length
58	
59	  return (
60	    <div className="flex flex-col min-h-0">
61	      <div className="flex items-center justify-between px-6 py-4 border-b border-border/50">
62	        <Typography variant="h1">Team &amp; Roles</Typography>
63	        <Button size="sm" onClick={() => setShowInviteModal(true)}>
64	          + Invite Member
65	        </Button>
66	      </div>
67	
68	      <Tabs defaultValue="members" className="mt-0 flex-1">
69	        <TabsList className="w-full justify-start border-b rounded-none bg-transparent h-auto px-6 gap-0">
70	          <TabsTrigger
71	            value="members"
72	            className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary px-4 pb-3 pt-0 text-sm font-medium"
73	          >
74	            Members {!loading && `(${activeCount})`}
75	          </TabsTrigger>
76	          <TabsTrigger
77	            value="invites"
78	            className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary px-4 pb-3 pt-0 text-sm font-medium"
79	          >
80	            Pending Invites {!loading && pendingCount > 0 && `(${pendingCount})`}
81	          </TabsTrigger>
82	        </TabsList>
83	
84	        <TabsContent value="members" className="mt-0 p-6">
85	          <DataState
86	            data={members}
87	            isLoading={loading}
88	            isError={!!fetchError}
89	            error={fetchError}
90	            loadingSlot={<ListSkeleton rows={4} />}
91	            emptySlot={
92	              <EmptyState
93	                icon={Mail}
94	                title="No team members yet"
95	                description="Invite artists and receptionists to join your studio."
96	                cta={{ label: 'Invite member', onClick: () => setShowInviteModal(true) }}
97	                variant="first-time"
98	              />
99	            }
100	            errorSlot={
101	              <PageError
102	                error={fetchError ?? new Error('Failed to load team')}
103	                reset={() => void fetchData()}
104	                variant="inline"
105	              />
106	            }
107	          >
108	            {(data) => (
109	              <TeamMembersTable
110	                members={data}
111	                currentUserId={currentUserId}
112	                onRefresh={() => void fetchData()}
113	              />
114	            )}
115	          </DataState>
116	        </TabsContent>
117	
118	        <TabsContent value="invites" className="mt-0 p-6">
119	          <DataState
120	            data={invites}
121	            isLoading={loading}
122	            isError={!!fetchError}
123	            error={fetchError}
124	            loadingSlot={<ListSkeleton rows={2} />}
125	            emptySlot={
126	              <EmptyState
127	                icon={Mail}
128	                title="No pending invites"
129	                description="Invited members will appear here until they accept."
130	                variant="default"
131	              />
132	            }
133	          >
134	            {(data) => (
135	              <TeamInvitesTable
136	                invites={data}
137	                onRefresh={() => void fetchData()}
138	              />
139	            )}
140	          </DataState>
141	        </TabsContent>
142	      </Tabs>
143	
144	      {showInviteModal && (
145	        <InviteModal
146	          open={showInviteModal}
147	          onOpenChange={setShowInviteModal}
148	          onSuccess={() => void fetchData()}
149	        />
150	      )}
151	    </div>
152	  )
153	}
